window.ScripturaLexicons.BDAG_PART_0138 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epithumia-bdag\" data-source=\"BDAG\" data-search=\"ἐπιθυμία, ας, ἡ epithumía substantivo feminino desejo; anseio; cobiça; concupiscência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιθυμία, ας, ἡ</td><td>substantivo feminino</td><td>desejo; anseio; cobiça; concupiscência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epithyo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιθύω epithýō verbo oferecer sacrifício BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιθύω</td><td>verbo</td><td>oferecer sacrifício</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikathizo-bdag\" data-source=\"BDAG\" data-search=\"ἐπικαθίζω epikathízō verbo sentar-se sobre; pôr sobre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικαθίζω</td><td>verbo</td><td>sentar-se sobre; pôr sobre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikathupnoo-bdag\" data-source=\"BDAG\" data-search=\"ἐπικαθυπνόω epikathupnóō verbo adormecer sobre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικαθυπνόω</td><td>verbo</td><td>adormecer sobre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikaio-bdag\" data-source=\"BDAG\" data-search=\"ἐπικαίω epikaíō verbo queimar superficialmente; abrasar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικαίω</td><td>verbo</td><td>queimar superficialmente; abrasar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikaleo-bdag\" data-source=\"BDAG\" data-search=\"ἐπικαλέω epikaléō verbo invocar; chamar por nome; recorrer; apelar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικαλέω</td><td>verbo</td><td>invocar; chamar por nome; recorrer; apelar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikalumma-bdag\" data-source=\"BDAG\" data-search=\"ἐπικάλυμμα, ατος, τό epikálumma substantivo neutro cobertura; véu; disfarce BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικάλυμμα, ατος, τό</td><td>substantivo neutro</td><td>cobertura; véu; disfarce</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikalupto-bdag\" data-source=\"BDAG\" data-search=\"ἐπικαλύπτω epikalúptō verbo cobrir; encobrir; perdoar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικαλύπτω</td><td>verbo</td><td>cobrir; encobrir; perdoar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikatallassomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπικαταλλάσσομαι epikatallássomai verbo reconciliar-se com BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικαταλλάσσομαι</td><td>verbo</td><td>reconciliar-se com</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikataratos-bdag\" data-source=\"BDAG\" data-search=\"ἐπικατάρατος, ον epikatáratos adjetivo amaldiçoado; sob condenação divina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικατάρατος, ον</td><td>adjetivo</td><td>amaldiçoado; sob condenação divina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikeimai-bdag\" data-source=\"BDAG\" data-search=\"ἐπίκειμαι epíkeimai verbo estar sobre; pressionar; impor-se; insistir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπίκειμαι</td><td>verbo</td><td>estar sobre; pressionar; impor-se; insistir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikello-bdag\" data-source=\"BDAG\" data-search=\"ἐπικέλλω epikéllō verbo encalhar; levar um navio à costa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικέλλω</td><td>verbo</td><td>encalhar; levar um navio à costa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikerdaino-bdag\" data-source=\"BDAG\" data-search=\"ἐπικερδαίνω epikerdaínō verbo obter ganho adicional BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικερδαίνω</td><td>verbo</td><td>obter ganho adicional</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikephalaion-bdag\" data-source=\"BDAG\" data-search=\"ἐπικεφάλαιον, ου, τό epikephálaion substantivo neutro imposto por cabeça; capitação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικεφάλαιον, ου, τό</td><td>substantivo neutro</td><td>imposto por cabeça; capitação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikoureios-bdag\" data-source=\"BDAG\" data-search=\"Ἐπικούρειος, ου, ὁ Epikoúreios substantivo masculino; nome de escola filosófica epicurista; discípulo de Epicuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐπικούρειος, ου, ὁ</td><td>substantivo masculino; nome de escola filosófica</td><td>epicurista; discípulo de Epicuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikouria-bdag\" data-source=\"BDAG\" data-search=\"ἐπικουρία, ας, ἡ epikouría substantivo feminino auxílio; socorro; ajuda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικουρία, ας, ἡ</td><td>substantivo feminino</td><td>auxílio; socorro; ajuda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikrazo-bdag\" data-source=\"BDAG\" data-search=\"ἐπικράζω epikrázō verbo gritar ameaças contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικράζω</td><td>verbo</td><td>gritar ameaças contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epikrino-bdag\" data-source=\"BDAG\" data-search=\"ἐπικρίνω epikrínō verbo decidir; determinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπικρίνω</td><td>verbo</td><td>decidir; determinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epilambanomai-bdag\" data-source=\"BDAG\" data-search=\"ἐπιλαμβάνομαι epilambánomai verbo agarrar; prender; apreender; ajudar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιλαμβάνομαι</td><td>verbo</td><td>agarrar; prender; apreender; ajudar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-epilampo-bdag\" data-source=\"BDAG\" data-search=\"ἐπιλάμπω epilámpō verbo resplandecer; brilhar; irradiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐπιλάμπω</td><td>verbo</td><td>resplandecer; brilhar; irradiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-epithumia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιθυμία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epithumía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver <span class=\"greek\">ἐπιθυμέω</span>; filósofos pré-socráticos, Heródoto e posteriores.)</p>\n<p class=\"entry-text\"><b>① Desejo intenso por alguma coisa: desejo, anseio, aspiração, ânsia.</b></p>\n<p class=\"entry-text\"><b>ⓐ Como termo neutro</b>, em Heródoto, Platão, Tucídides e outros: <span class=\"greek\">αἱ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λοιπὰ</span> <span class=\"greek\">ἐ</span>., <i>desejos por outras coisas</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:19</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">πράξεων</span> <span class=\"greek\">πολλῶν</span>, <i>desejo de muitas atividades</i>, Hm 6, 2, 5 (mas também é possível a acepção ② abaixo). <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span>, <i>desejo da alma</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:14</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Do desejo de coisas boas</b> (Diod. S. 11, 36, 5: <span class=\"greek\">ἐπιθ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλευθερίας</span> = <i>da liberdade</i>; Pv 10:24: <span class=\"greek\">ἐ</span>. <span class=\"greek\">δικαίου</span> <span class=\"greek\">δεκτή</span>; <span class=\"greek\">ἄνερ</span> <span class=\"greek\">ἐπιθυμιῶν</span>, GrBar 1:3; Jos., C. Ap. 1, 111): <span class=\"greek\">ἐπιθυμίαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, <i>ter anseio por alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:23</a> (<span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔχειν</span> como em Jos., C. Ap. 1, 255; <span class=\"greek\">ἐ</span>. <span class=\"greek\">εἰς</span> como em Tucídides 4, 81, 2). <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">ἐπιθυμεῖν</span> (Gn 31:30), <i>desejar ardentemente</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:15</a> (ver <span class=\"greek\">ἐπιθυμέω</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλῇ</span> <span class=\"greek\">ἐ</span>., <i>com grande anseio</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 2:17</a>. <span class=\"greek\">ἐλπίζει</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπιθυμίᾳ</span> <span class=\"greek\">μου</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">παραλελοιπέναι</span> <span class=\"greek\">τι</span>, <i>espero que, de acordo com meu desejo, nada tenha sido omitido</i>, B 17:1. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγρυπνία</span>, B 21:7. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀγαθὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σεμνήν</span>, Hm 12, 1, 1.</p>\n<p class=\"entry-text\"><b>② Desejo por alguma coisa proibida ou simplesmente excessiva: cobiça, concupiscência, desejo desordenado.</b> (Já em Platão, Phd. 83b: <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">φιλοσόφου</span> <span class=\"greek\">ψυχὴ</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">ἀπέχεται</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡδονῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιθυμιῶν</span> <span class=\"greek\">κτλ</span>.; Polystrat., p. 30; Duris [séc. III a.C.], 76, fragmento 15 Jac.; depois, sobretudo, os estoicos [E. Zeller, <i>Philos. d. Griechen</i> III/1⁴, 1909, pp. 235ss.], por exemplo Epict. 2, 16, 45; 2, 18, 8s.; 3, 9, 21 e outros; Maximus Tyr. 24, 4a: <span class=\"greek\">μέγιστον</span> <span class=\"greek\">ἀνθρώπῳ</span> <span class=\"greek\">κακὸν</span> <span class=\"greek\">ἐπιθυμία</span>; Herm. Wr. 1, 23; 12, 4, também Stob., p. 444, 10 Sc.; Wsd 4:12; Sir 23:5; 4 Mac 1:22; 3:2 e outros; ApcMos 19: <span class=\"greek\">ἐ</span>. … <span class=\"greek\">κεφαλὴ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἁμαρτίας</span>; Fílon, Spec. Leg. 4, 93, Leg. All. 2, 8, Vi. Cont. 74; Jos., Bell. 7, 261, Ant. 4, 143), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:7</a>s.; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1:14</a>s.; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 1:4</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">πονηρά</span>, <i>desejo maligno</i> (Xen., Mem. 1, 2, 64; Ar. 8, 4), Hv 1, 2, 4; 3, 7, 3; 3, 8, 4; m 8:5 [assim na fonte]. <span class=\"greek\">ἐ</span>. <span class=\"greek\">κακή</span>, <i>mau desejo</i> (Platão, Leg. 9, 854a; Pv 12:12; 21:26; Just., A I, 10, 6), Cl 3:5.</p>\n<p class=\"entry-text\"><b>Do desejo sexual:</b> (Já em Alceu, segundo Plut., Mor. 525ab; lâmina de maldição de Hadrumeto, linha 7, em Dssm., B 28 [BS 273ss.] e IDefixWünsch n.º 5, p. 23; PGM 17a, 9; 21; Sus Theod. 8; 11; 14 e outros; LXX 32; Jos., Ant. 4, 130; 132; Ath. 33, 1: <span class=\"greek\">μέτρον</span> <span class=\"greek\">ἐπιθυμίας</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παιδοποιία</span>; Did., Gen. 151, 27: <span class=\"greek\">ἄλογος</span> <span class=\"greek\">ἐ</span>.), D 3:3. <span class=\"greek\">πάθος</span> <span class=\"greek\">ἐπιθυμίας</span>, <i>paixão do desejo</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 4:5</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἐπιθυμίαν</span> (cf. Epict. 3, 15, 7; M. Ant. 2, 10, 1; 2; 3; Just., A II, 5, 4; Ath. 21, 1), <i>de acordo apenas com o desejo físico</i>, IPol 5:2. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἐπιθυμίαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνθρώπων</span>, Ox 840, 38 (Ps.-Platão, Eryx. 21, 401e: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐπιθυμίας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span> = <i>para satisfazer os desejos do corpo</i>; cf. 405e: jogo de azar, embriaguez e gula são chamados <span class=\"greek\">ἐπιθυμίαι</span>. Em Ox 840, 38, como o <span class=\"greek\">ν</span> de <span class=\"greek\">ἐπιθυμίαν</span> está ausente e foi restaurado, a palavra também pode ser <span class=\"greek\">ἐπιθυμίας</span>). <span class=\"greek\">ἐ</span>. <span class=\"greek\">γυναικός</span> (Dn 11:37), Hm 6, 2, 5; 12, 2, 1.</p>\n<p class=\"entry-text\"><b>Plural.</b> (Frequentemente na LXX; EpArist 256; Fílon.) Com <span class=\"greek\">παθήματα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:24</a>. Numa lista de vícios (cf. Fílon, Congr. Erud. Grat. 172, Migr. Abr. 60, Vi. Cont. 2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 4:3</a>; D 5:1. <span class=\"greek\">ἐ</span>. <span class=\"greek\">πολλαὶ</span> <span class=\"greek\">ἀνόητοι</span>, <i>muitos desejos insensatos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6:9</a>; <span class=\"greek\">νεωτερικαὶ</span> <span class=\"greek\">ἐ</span>., <i>desejos juvenis</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2:22</a> (W. Metzger, TZ 33 [1977], pp. 129–136); <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἰδίας</span> <span class=\"greek\">ἐ</span>., <i>segundo os próprios desejos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 4:3</a>; cf. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἰ</span>. <span class=\"greek\">ἐ</span>., Pol. 7:1; <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτῶν</span>, AcPl Ha 8, 20 (para isso, <span class=\"greek\">ἀνομίας</span> em AcPl BMM, recto, 26, restaurado conforme Ox 1602, 27). <span class=\"greek\">αἱ</span> <span class=\"greek\">πρότερον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀγνοίᾳ</span> <span class=\"greek\">ἐ</span>., <i>os desejos que outrora vos dominavam, quando éreis ignorantes</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:14</a>.</p>\n<p class=\"entry-text\"><b>Com genitivo:</b> genitivo subjetivo: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀνθρώπων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 4:2</a>; <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ὑμῶν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:44</a>; genitivo de qualidade: <span class=\"greek\">ἐ</span>. <span class=\"greek\">μιασμοῦ</span>, <i>paixão aviltante</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2:10</a>; cf. <span class=\"greek\">μιαρὰς</span> <span class=\"greek\">ἐ</span>., 1 Cl 28:1; <span class=\"greek\">βδελυκτὰς</span> <span class=\"greek\">ἐ</span>., 1 Cl 30:1. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπάτης</span>, <i>desejos enganadores</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 4:22</a>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ματαίων</span>, 2 Cl 19:2; cf. Hm 11, 8. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀσεβειῶν</span>, Jd 18. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρίας</span>, <i>desejo maligno</i>, Hv 1, 1, 8. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀσελγείας</span>, Hv 3, 7, 2. O genitivo também pode indicar a origem e a sede do desejo: <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">καρδιῶν</span>, <i>dos corações</i> (Sir 5:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:24</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> … <span class=\"greek\">τῆς</span> <span class=\"greek\">πονηρᾶς</span>, 1 Cl 3:4. <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θνητοῦ</span> <span class=\"greek\">σώματος</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:12</a> (Ps.-Platão, Eryx. 21, 401e, ver acima; Sextus 448: <span class=\"greek\">ἐπιθυμίαι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>). <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:3</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2:16</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2:18</a>; B 10, 9. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφθαλμῶν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Jo 2:16</a>; para designar algo a que pertence o desejo, em geral, versículo 17; <span class=\"greek\">σαρκικαὶ</span> <span class=\"greek\">ἐ</span>. (Hippol., Ref. 5, 9, 22; Did., Gen. 62, 3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:11</a>; D 1:4; <span class=\"greek\">σωματικαὶ</span> <span class=\"greek\">ἐ</span>. (4 Mac 1:32), no mesmo lugar; <span class=\"greek\">κοσμικαὶ</span> <span class=\"greek\">ἐ</span>., <i>desejos mundanos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 2:12</a>; 2 Cl 17:3; <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span>, Pol. 5:3.</p>\n<p class=\"entry-text\"><span class=\"greek\">εἰς</span> <span class=\"greek\">ἐ</span>., <i>para despertar desejos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 13:14</a>; <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>., <i>agir segundo os desejos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.44\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:44</a>. <span class=\"greek\">τελεῖν</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">σαρκός</span>, <i>satisfazer os desejos da carne</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 5:16</a>; <span class=\"greek\">ὑπακούειν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐ</span>., <i>obedecer aos desejos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:12</a>; <span class=\"greek\">δουλεύειν</span> <span class=\"greek\">ἐ</span>., <i>ser escravo dos desejos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 3:3</a>; cf. <span class=\"greek\">δοῦλος</span> <span class=\"greek\">ἐπιθυμίας</span>, IPol 4:3. <span class=\"greek\">ἄγεσθαι</span> <span class=\"greek\">ἐπιθυμίαις</span>, <i>ser conduzido pelos desejos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 3:6</a>. <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐ</span>., Jd 16; 18; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 3:3</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐπιθυμίαις</span> (Sir 5:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 4:3</a>; <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">αἰῶνος</span> <span class=\"greek\">τούτου</span>, Hs 6, 2, 3; 6, 3, 3; 7:2; 8, 11, 3. <span class=\"greek\">ἀναστρέφεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 2:3</a>.</p>\n<p class=\"entry-text\">— B. Easton, <i>Pastoral Ep.</i> (1947), pp. 186s.; RAC II 62–78. Ver <span class=\"greek\">πόθος</span>. — Schmidt, Syn. III 591–601; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-epithyo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιθύω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epithýō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέθυσα</span> (ver <span class=\"greek\">θύω</span>; Ésquilo e outros; OGI 222, 37; 332, 29; papiros [Mayser 33]; LXX; En 19:1). <b>Fazer uma oferta (a uma divindade), oferecer um sacrifício</b> (com <span class=\"greek\">ὀμνύναι</span>) como gesto patriótico, MPol 4; 8:2; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 14:13</a>, variante de leitura. — DELG, s.v. 2 <span class=\"greek\">θύω</span>.</p></section></article>\n<article id=\"entry-epikathizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικαθίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikathízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπικαθιῶ</span>, Ez 32:4, variante de leitura; primeiro aoristo <span class=\"greek\">ἐπεκάθισα</span>, LXX (ver <span class=\"greek\">καθίζω</span>; em vários sentidos, Tucídides e outros; também Jos., Ant. 18, 57).</p>\n<p class=\"entry-text\"><b>① Sentar-se ou assentar-se (sobre)</b>, intransitivo (Plut., Them. 118 [12, 1]; Gn 31:34; 2 Km 13:29; TestSol 6:1 P); <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τινός</span>, <i>sobre alguma coisa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:7</a> (<span class=\"greek\">ἐπικαθίσας</span> em Just., D. 53, 2). A leitura <span class=\"greek\">ἐπεκάθισαν</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">αὐτόν</span> (א [corrigido de <span class=\"greek\">ἐκάθισαν</span>] e outros) conferiria ao verbo o sentido transitivo da acepção ②.</p>\n<p class=\"entry-text\"><b>② Colocar ou pôr sobre</b> (Hipócrates, Art. 78: <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>; igualmente 3 Km 1:38, 44; Ez 32:4). — DELG, s.v. <span class=\"greek\">ἕζομαι</span> A; M-M.</p></section></article>\n<article id=\"entry-epikathupnoo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικαθυπνόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikathupnóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(<i>Hapax legomenon.</i>) <b>Adormecer sobre</b>, com dativo <span class=\"greek\">τινί</span>, <i>alguma coisa</i>: <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἁμαρτίαις</span>, B 4:13.</p></section></article>\n<article id=\"entry-epikaio-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικαίω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikaíō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">καίω</span>; mais-que-perfeito <span class=\"greek\">ἐπεκεκαύκειν</span> (encontrado em tmese já em Homero; Wsd 6720, 4). Em Homero, <i>queimar</i>; em nossa literatura, somente no sentido de <b>queimar a superfície, abrasar</b>, acerca do sol (Platão, Ep. 7, 340d: <span class=\"greek\">οἱ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σώματα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἡλίου</span> <span class=\"greek\">ἐπικεκαυμένοι</span>; igualmente Dio Chrys. 53 [70], 2; cf. Políbio 38, 8, 7). Emprego absoluto: <i>abrasar</i>, Hs 9, 1, 6.</p></section></article>\n<article id=\"entry-epikaleo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικαλέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikaléō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">καλέω</span>; primeiro aoristo <span class=\"greek\">ἐπεκάλεσα</span>; futuro médio <span class=\"greek\">ἐπικαλέσομαι</span>; primeiro aoristo médio <span class=\"greek\">ἐπεκαλεσάμην</span>. Passivo: primeiro futuro, terceira pessoa singular, <span class=\"greek\">ἐπικληθήσεται</span>; primeiro aoristo <span class=\"greek\">ἐπεκλήθην</span>; perfeito <span class=\"greek\">ἐπικέκλημαι</span>, particípio <span class=\"greek\">ἐπικεκλημένος</span>; mais-que-perfeito, terceira pessoa singular, <span class=\"greek\">ἐπεκέκλητο</span> (com tmese já em Homero; nos demais casos, Heródoto e outros; inscrições, papiros, LXX, pseudoepígrafos, Josefo).</p>\n<p class=\"entry-text\"><b>① Chamar uma divindade para qualquer fim: invocar, clamar.</b> («Invocar», Heródoto 2, 39; 3, 8.) 1 Cl 39:7 (Jó 5:1). Na voz média: <i>invocar, recorrer a alguém para obter algo</i> (<span class=\"greek\">ἐ</span>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span> em Heródoto e outros; Xen., Cyr. 7, 1, 35; Platão, Tim. 27c; Políbio 15, 1, 13; Diod. S. 5, 49, 5, acerca da invocação aos deuses por iniciados; Epict. 2, 7, 12; 3, 21, 12 e outros; Herm. Wr. 16, 3; OGI 194, 18 [séc. I a.C.]; preces de vingança de Reneia 1 [Dssm., LO 352ss./LAE 424ss.; SIG 1181]; POxy 1380, 153 [início do séc. II d.C.]; 886, 10 [séc. III d.C.]; PGM 3, 8; 43; 4, 1182; 1217; 1345; 13, 138; 270; LXX; PsSol 2:36 e outros; JosAs 25:7; EpArist 17; 193; 226; Jos., Ant. 4, 222 e outros). <span class=\"greek\">ἐπικαλεῖσθαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span> (1 Km 12:17s.; 2 Km 22:7; PsSol 9:6), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:12</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2:22</a>; 1 Cl 52:3 (Sl 49:15); 57:5 (Pv 1:28); 60:4. Também <span class=\"greek\">ἐπικαλεῖσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">κυρίου</span> (Gn 13:4; 21:33 e outros; Jos., Bell. 5, 438; PGM 1, 161; 4, 1209; 1609; 1811; 13, 871), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:21</a> (Jl 3:5); 9:14, 21; 22:16; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:13</a> (Jl 3:5); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1:2</a>; 1 Cl 64:1. Uso absoluto (Sl 4:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:14</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.59\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:59</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">πατέρα</span> <span class=\"greek\">ἐπικαλεῖσθέ</span> <span class=\"greek\">τινα</span>, <i>se invocais alguém como Pai</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1:17</a> (P 72: <span class=\"greek\">καλεῖτε</span>, que pode ser classificado sob ②). — J. Tyrer, JTS 25 (1924), pp. 139–150; resposta de R. Connolly, ibid., pp. 337–368; F. Nötscher, «Epiklese», Biblica 30 (1949), pp. 401–404 = <i>Vom A zum NT</i> (1962), pp. 221–225.</p>\n<p class=\"entry-text\"><b>② Dirigir-se a alguém ou caracterizá-lo por um termo especial: chamar, conferir sobrenome.</b> (Xenofonte, Platão e outros; OGI 603, 10; PFay 12, 1; PTebt 399, 15 e outros; 1 Mac 2:2.) Construção <span class=\"greek\">τινά</span> <span class=\"greek\">τι</span>: <span class=\"greek\">τὸν</span> <span class=\"greek\">οἰκοδεσπότην</span> <span class=\"greek\">Βεελζεβούλ</span>, <i>chamar Belzebu ao dono da casa</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:25</a>. Na passiva, <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπικαλούμενος</span>, <i>aquele que também é chamado</i> (Socrat., Ep. 21, 3; Diod. S. 3, 84, 1; Diog. L. 4, 18; Jos., Ant. 18, 206; PYadin 5a I, 5 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:18</a>; 11:13; 12:12. Com <span class=\"greek\">Συμεὼν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπικαλούμενος</span> <span class=\"greek\">Νίγερ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 13:1</a> D (cf. Diod. S. 17, 20, 7: <span class=\"greek\">Κλεῖτος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Μέλας</span> <span class=\"greek\">ἐπικαλούμενος</span>). <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:3</a>, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:22</a>, variante de leitura. Também <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπικληθείς</span> (Diog. L. 5, 58, acerca de Estratão de Lâmpsaco: <span class=\"greek\">φυσικὸς</span> <span class=\"greek\">ἐπικληθείς</span>; Jos., Bell. 1, 60, Ant. 13, 103; Just., D. 106, 3; Ath. 28, 4), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:3</a>, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 4:36</a>; 12:25; GEb 34, 59. <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἐπικαλεῖται</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:5</a>, 32; <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἐπεκλήθη</span> (Jos., Ant. 13, 218; 271), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:23</a>; cf. Papias 2:9. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπαισχύνεται</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐπικαλεῖσθαι</span> <span class=\"greek\">αὐτῶν</span>, <i>ser chamado Deus deles</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:16</a>.</p>\n<p class=\"entry-text\">A passiva emprega-se com <span class=\"greek\">ὄνομα</span>, como no Antigo Testamento, em <span class=\"greek\">ἐπικαλεῖται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>: <i>o nome de alguém é pronunciado sobre outro, designando este como propriedade daquele</i> (K. Galling, TLZ 81 [1956], pp. 65–70; quanto ao nome de Deus, 2 Km 6:2; 3 Km 8:43; Jr 7:30; 14:9 e frequentemente), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:17</a> (Am 9:12; também 2 Cr 7:14). <span class=\"greek\">τὸ</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐπικληθὲν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ὑμᾶς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2:7</a>; cf. Hs 8, 6, 4. De modo semelhante, <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐπικαλούμενοι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">αὐτοῦ</span>, <i>os que são chamados pelo seu nome</i>, Hs 9, 14, 3 (cf. Is 43:7).</p>\n<p class=\"entry-text\"><b>③ Requerimento dirigido à autoridade judicial superior para revisão de decisão de tribunal inferior: apelação, recorrer</b>, voz média, termo técnico jurídico; com <span class=\"greek\">τινά</span>, <i>a alguém</i>; corresponde ao latim <i>provocatio</i> contra a <i>coercitio</i> de um governador provincial (cf. Plut., Marcell. 299 [2, 7], Tib. Gracch. 832 [16, 1]). <span class=\"greek\">Καίσαρα</span>, <i>apelar a César</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:11</a>s.; 26:32; 28:19; também <span class=\"greek\">τὸν</span> <span class=\"greek\">Σεβαστόν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:25</a>. Seguido de infinitivo: <span class=\"greek\">τοῦ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">Παύλου</span> <span class=\"greek\">ἐπικαλεσαμένου</span> <span class=\"greek\">τηρηθῆναι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σεβαστοῦ</span> <span class=\"greek\">διάγνωσιν</span>, <i>quando Paulo apelou para ser mantido sob custódia a fim de aguardar a decisão do imperador</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 25:21</a>. — A. Sherwin-White, <i>Roman Society and Law in the NT</i> (1963), pp. 57–70; A. H. M. Jones, <i>Studies in Roman Government and Law</i> (1960), pp. 53ss.; BAFCS III, índice.</p>\n<p class=\"entry-text\"><b>④ Invocar num juramento: chamar alguém como testemunha</b>, voz média, com <span class=\"greek\">τινὰ</span> <span class=\"greek\">μάρτυρα</span>, termo técnico jurídico (Platão, Leg. 2, 664c), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 1:23</a> (<span class=\"greek\">θεοὺς</span> <span class=\"greek\">ἐπικαλεῖσθαι</span> <span class=\"greek\">μάρτυρας</span>: Políbio 11, 6, 4; Heliod. 1, 25, 1; Jos., Ant. 1, 243). — M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-epikalumma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικάλυμμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikálumma⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Ver o verbete seguinte; «cobertura» em Aristóteles e outros; LXX.) <b>Estratagema empregado para ocultar alguma coisa: cobertura, véu, disfarce.</b> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κακίας</span>, <i>cobertura para a maldade</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 2:16</a> (Menandro, Fgm. 90 Kock: <span class=\"greek\">πλοῦτος</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐπικάλυμμ</span>’ <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">κακῶν</span>, <i>a riqueza é encobrimento de muitos males</i>; Irineu, s.v. <span class=\"greek\">κακία</span> 1). — DELG, s.v. <span class=\"greek\">καλύπτω</span>.</p></section></article>\n<article id=\"entry-epikalupto-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικαλύπτω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikalúptō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro <span class=\"greek\">ἐπικαλύψω</span>; primeiro aoristo <span class=\"greek\">ἐπικάλυψα</span>, LXX. Passivo: primeiro aoristo <span class=\"greek\">ἐπεκαλύφθην</span>; particípio perfeito <span class=\"greek\">ἐπικεκαλυμμένος</span>, 2 Km 5:30 (ver o verbete precedente; Hesíodo e outros; Just., D. 68, 6 e 130, 1: <span class=\"greek\">ἐπικεκαλυμμένως</span>). «Ocultar da vista cobrindo»; depois, por extensão figurada, como sinônimo de «perdoar»: <b>encobrir.</b> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐπεκαλύφθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἁμαρτίαι</span>, <i>cujos pecados foram encobertos, afastados da vista</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4:7</a>; 1 Cl 50:6 (ambos citando Sl 31:1).</p></section></article>\n<article id=\"entry-epikatallassomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικαταλλάσσομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikatallássomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Segundo aoristo <span class=\"greek\">ἐπικατηλλάγην</span> (<i>hapax legomenon</i>). Com dativo <span class=\"greek\">τινί</span>, <b>reconciliar-se com alguém</b>, 1 Cl 48:1. — DELG, s.v. <span class=\"greek\">ἄλλος</span>.</p></section></article>\n<article id=\"entry-epikataratos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικατάρατος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikatáratos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">καταράομαι</span>; inscrição da Eubeia, SIG 1240, 2 [séc. II d.C.], e de Halicarnasso, CIG 2664 [séculos II/III d.C.]; Vi. Aesopi G 3 P.: <span class=\"greek\">ἐπικατάρατε</span>; escólio a Sófocles, Ant. 867, p. 258 Papag. [1888]; LXX; Fílon, Leg. All. 3, 111; 113; En 102:3; TestSol 20:6 P; ApcMos; Dssm., LO 74s. [LAE 93s.]. <b>Relativo a estar sob condenação divina: amaldiçoado.</b> <span class=\"greek\">ἐ</span>. <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὸ̔ς</span> …, <i>amaldiçoado seja todo aquele que …</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3:10</a> (Dt 27:26; Just., D. 89, 2; 96, 1), 13. Com <span class=\"greek\">παραβάτης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νόμου</span> e em oposição a <span class=\"greek\">μακάριος</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:4</a> D. <span class=\"greek\">ἐ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">εἷς</span>, B 7:7; cf. 9. De peixes amaldiçoados, que devem viver nas profundezas do mar, B 10:5. — M-M.</p></section></article>\n<article id=\"entry-epikeimai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπίκειμαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epíkeimai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Imperfeito <span class=\"greek\">ἐπεκείμην</span> (Homero e posteriores).</p>\n<p class=\"entry-text\"><b>① Estar em algum lugar em contato com uma superfície: jazer sobre, estar colocado sobre.</b> Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, <i>sobre alguma coisa</i> (Pausânias 5, 10, 2): de uma pedra, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:38</a> (J. Swetnam, CBQ 28 [1966], pp. 155–173). Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span>, <i>sobre alguma coisa</i> (Cass. Dio 67, 16; Herm. Wr. 1, 13b): da serpente de bronze, B 12:7. <span class=\"greek\">τὰ</span> <span class=\"greek\">στόματα</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐπικείμενα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πίνοντα</span>, <i>(vi como) as bocas deles (dos cabritos) estavam junto à água, mas não bebiam</i>, GJs 18:3. Emprego absoluto: <span class=\"greek\">ὀψάριον</span> <span class=\"greek\">ἐπικείμενον</span>, <i>peixe colocado sobre ela</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:9</a> (cf. PTebt 47, 25 [113 a.C.]; PGrenf II, 57, 9: <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπικειμένην</span> <span class=\"greek\">σποράν</span>; 2 Mac 1:21). Em sentido imagético, <i>estar sobre</i>, acerca da imagem numa moeda, IMg 5:2.</p>\n<p class=\"entry-text\"><b>② Exercer força ou pressão sobre alguém ou alguma coisa.</b></p>\n<p class=\"entry-text\"><b>ⓐ Quanto à força pessoal: apertar ao redor, pressionar, insistir.</b> Com dativo de pessoa (Xen., An. 4, 3, 7; Arrian., An. 1, 14, 5; Esopo, fab. 140 P. = 249 H.; Jó 19:3; 21:27; Jos., Ant. 6, 334 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:1</a>.</p>\n<p class=\"entry-text\"><b>ⓑ Quanto à força impessoal: confrontar, impor-se.</b> <span class=\"greek\">χειμῶνος</span> <span class=\"greek\">ἐπικειμένου</span>, <i>visto que uma tempestade caía sobre nós</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:20</a> (cf. Plut., Timol. 250 [28, 7]; Wsd 17:20, variante de leitura). <span class=\"greek\">ἀνάγκη</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐπίκειται</span>, <i>uma necessidade me é imposta</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 9:16</a> (cf. Il. 6, 459; SibOr 3, 572). <span class=\"greek\">ἀγὼν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἐπίκειται</span>, <i>um conflito nos confronta</i>, 1 Cl 7:1; <span class=\"greek\">μέγας</span> <span class=\"greek\">ἐπίκειται</span> <span class=\"greek\">πιρασμός</span>, <i>uma séria tentação confronta (Paulo)</i>, AcPl Ha 8, 22. Em sentido um tanto enfraquecido, <i>estar diante de</i> (Achilles Tat. 2, 16, 2): <span class=\"greek\">ὁ</span> <span class=\"greek\">τοκετός</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐπίκειται</span>, <i>as dores do parto (figura dos tormentos vindouros) estão sobre mim</i>, IRo 6:1.</p>\n<p class=\"entry-text\"><b>③ Ter força de obrigação: ser imposto, incumbir.</b> (Lucian., Cal. 17; Ar. 7:3: <span class=\"greek\">θάνατος</span>; 1 Mac 6:57; Just., D. 53, 4: <span class=\"greek\">τὸν</span> … <span class=\"greek\">νόμον</span> <span class=\"greek\">ἐπικείμενον</span> <span class=\"greek\">ἔχετε</span>; TestJob 15:3 e Just., A I, 12, 3: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐπικείμενα</span>.) <span class=\"greek\">δικαιώματα</span> <span class=\"greek\">ἐπικείμενα</span>, <i>regulamentos impostos</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:10</a>. <span class=\"greek\">διακονίαι</span> <span class=\"greek\">ἐπίκεινταί</span> <span class=\"greek\">τινι</span>, <i>deveres são impostos a alguém</i>, 1 Cl 40:5. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κατέξω</span> <span class=\"greek\">τ̣ὰ</span> [<span class=\"greek\">προς</span>]|<span class=\"greek\">τεταγμένα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπεικίμ̣</span>[<span class=\"greek\">εν</span>]<span class=\"greek\">α</span>, <i>para que eu não deixe de cumprir minhas tarefas e obrigações</i>, AcPl Ha 7, 15.</p>\n<p class=\"entry-text\"><b>④ Continuar a fazer alguma coisa com insistência: instar, exigir com urgência.</b> <span class=\"greek\">ἐπέκειντο</span> <span class=\"greek\">αἰτούμενοι</span>, <i>exigiam insistentemente</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:23</a> (cf. Heródoto 5, 104; Jos., Ant. 18, 184: <span class=\"greek\">πολλῷ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἐπέκειτο</span> <span class=\"greek\">ἀξιῶν</span>; também 20, 110).</p>\n<p class=\"entry-text\"><b>⑤ Existir como possibilidade: estar disponível.</b> <span class=\"greek\">τούτοις</span> <span class=\"greek\">ἐπίκειται</span> <span class=\"greek\">μετάνοια</span>, <i>o arrependimento está aberto para eles</i>, Hs 8, 7, 2, variante de leitura. — M-M; TW.</p></section></article>\n<article id=\"entry-epikello-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικέλλω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikéllō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέκειλα</span>. Termo técnico náutico («trazer [uma embarcação] à costa» em Apolônio de Rodes 1, 1362; 2, 352 e outros). <b>Encalhar.</b> <span class=\"greek\">ἐ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ναῦν</span> (cf. Od. 9, 148; 546), <i>fazer o navio encalhar</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:41</a> (variante de leitura <span class=\"greek\">ἐπώκειλαν</span>). — DELG, s.v. <span class=\"greek\">κέλλω</span>; M-M.</p></section></article>\n<article id=\"entry-epikerdaino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικερδαίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikerdaínō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Plut., Flam. 370 [3, 2]; Cass. Dio 36, 12; Sb IV, 7464, 15 [séc. III d.C.].) <b>Obter ganho adicional</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:20</a> e 22, variantes de leitura. — DELG, s.v. <span class=\"greek\">κέρδος</span>.</p></section></article>\n<article id=\"entry-epikephalaion-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικεφάλαιον, ου, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikephálaion⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><b>Imposto por cabeça, capitação</b> (Aristóteles, Oec. 2, 1346a, 4; papiros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12:14</a>, variante de leitura (em lugar de <span class=\"greek\">κῆνσον</span>). — DELG, s.v. <span class=\"greek\">κεφαλή</span>; M-M.</p></section></article>\n<article id=\"entry-epikoureios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐπικούρειος, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Epikoúreios⟧</span><span class=\"separator\">·</span><span>substantivo masculino; nome de escola filosófica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Numênio [ver <span class=\"greek\">στρεβλόω</span> 2] 1, 3, p. 63; Alciphron 3, 19, 3; Diog. L. 10, 3; 31; SIG 1227: <span class=\"greek\">φιλόσοφος</span> <span class=\"greek\">Ἐπικούρειος</span>; IGR IV, 997; Jos., Ant. 10, 277; 19, 32; Just., A II, 15, 3. Para a grafia [-<span class=\"greek\">ριος</span> em Tdf., W-H., Sod.], ver W-S. §5, 13e; cf. Fílon, Poster. Cai. 2.) <b>Um epicurista, seguidor de Epicuro</b>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:18</a> (ver comentários). — R. Hicks, EncRelEth V, pp. 324–330; W. de Witt, <i>Epicurus and His Philosophy</i> (1954); W. Barclay, ET 72 (1960), pp. 78–81; 72 (1961), pp. 101–104, 146–149; E. Asmis, <i>Epicurus’ Scientific Method</i> (1984); RAC V 681–819. — M-M.</p></section></article>\n<article id=\"entry-epikouria-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικουρία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikouría⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(De <span class=\"greek\">ἐπικουρέω</span>, «servir como aliado, prestar auxílio»; trágicos, Heródoto e outros; Diod. S. 1, 90, 2; Appian., Syr. 37 §192: <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐ</span>.; SIG 1015, 24 [séc. III a.C.]; PFlor 382, 40; Wsd 13:18; Fílon, Spec. Leg. 1, 298: <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>; Jos., Ant. 1, 281: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐμὴ</span> [= <span class=\"greek\">θεοῦ</span>] <span class=\"greek\">ἐ</span>.; 20, 56.) <b>Ajuda, auxílio, socorro.</b> <span class=\"greek\">ἐπικουρίας</span> <span class=\"greek\">τυχὼν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span>, <i>tendo recebido ajuda da parte de Deus</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:22</a> (Jos., Ant. 2, 94: <span class=\"greek\">ἐπικουρίας</span> <span class=\"greek\">τυγχάνειν</span>). Em Il. 5, 514, o verbo <span class=\"greek\">ἐπικουρέω</span> se refere a servir como aliado (cf. Isócrates 4, 168), e é provável que nossa passagem se refira a Deus vindo ao socorro com auxílio de um aliado (para outras referências, ver L-S-J-M, s.v. <span class=\"greek\">ἐπικουρέω</span> e cognatos). — B. 1354, o verbo; New Docs 3, pp. 67s.; DELG, s.v. <span class=\"greek\">ἐπίκουρος</span>; M-M.</p></section></article>\n<article id=\"entry-epikrazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικράζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikrázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">(Luciano, Anach. 16; Pólux 5, 85; TestSol 26:9 H [«chamar»].) <b>Gritar ameaças</b>, com <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>, <i>contra alguém</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:39</a>, variante de leitura. Seguido de discurso direto, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:19</a>, variante de leitura.</p></section></article>\n<article id=\"entry-epikrino-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπικρίνω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epikrínō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Primeiro aoristo <span class=\"greek\">ἐπέκρινα</span>; particípio feminino do primeiro aoristo passivo <span class=\"greek\">ἐπικριθεῖσαν</span>, 3 Mac 4:2 (ver <span class=\"greek\">κρίνω</span>; Platão e outros; inscrições, papiros, LXX, Fílon; Jos., Bell. 6, 416, Ant. 14, 192). <b>Chegar a uma decisão em alguma questão: decidir, determinar.</b> Seguido de acusativo e infinitivo (SIG 1109, 71): <span class=\"greek\">ἐπέκρινεν</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἴτημα</span> <span class=\"greek\">αὐτῶν</span>, <i>decidiu que a exigência deles devia ser atendida</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:24</a>. — Quanto a <span class=\"greek\">ἐπίκριμα</span>, «decreto», ver Cyr. Ins. 68. — M-M; TW.</p></section></article>\n<article id=\"entry-epilambanomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιλαμβάνομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epilambánomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Ver <span class=\"greek\">λαμβάνω</span>; futuro <span class=\"greek\">ἐπιλήψομαι</span>, LXX; segundo aoristo <span class=\"greek\">ἐπελαβόμην</span>; particípio perfeito feminino <span class=\"greek\">ἐπειλημμένη</span>, Gn 25:26 (em nossa literatura, assim como na LXX e em TestJos 8:2, somente na voz média, usada desde Heródoto; também inscrições, papiros; Fílon, Somn. 2, 68; Jos., Bell. 6, 232; Justino).</p>\n<p class=\"entry-text\"><b>① Fazer o movimento de agarrar ou segurar alguma coisa: apoderar-se de, agarrar, segurar, apanhar.</b> Às vezes com violência, seguido de genitivo (Heródoto 6, 114 e outros; LXX): de pessoa (Laud. Therap. 24: <span class=\"greek\">ἐπιλαμβάνονται</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνδρός</span>; 2 Km 13:11; Is 3:6), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:31</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:26</a>, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 17:19</a>; 21:30, 33 (ver ② abaixo); de coisa (LXX): <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span> <span class=\"greek\">τινος</span>, <i>da mão de alguém</i> (cf. Platão, Prot. 335c; Zc 14:13; Jos., Ant. 9, 180), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:23</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 23:19</a>; figuradamente, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:9</a> (Jr 38:32). Seguido de genitivo de pessoa e da coisa pela qual se agarra a pessoa (Xen., An. 4, 7, 12: <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἴτυος</span>, «do escudo dele»; Diod. S. 17, 30, 4; Epict. 1, 29, 23; Bel 36 LXX; TestJos 8:2): <span class=\"greek\">μου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span>, <i>a mim, pela mão</i>, Hv 3, 2, 4 (Plut., Mor. 207c: <span class=\"greek\">ἐπιλαβόμενος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span>). <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πήρας</span>, <i>a ele, pela mochila</i>, Hs 9, 10, 5. Com acusativo de pessoa (cf. Platão, Leg. 6, 779c), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:47</a>; <i>recrutar compulsoriamente para o serviço</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23:26</a> (quanto ao empréstimo <span class=\"greek\">ἀγγαρεύω</span>, ver esse verbete). Frequentemente, onde <span class=\"greek\">ἐ</span>. parece reger o acusativo, esse caso é na realidade o objeto do verbo finito de que <span class=\"greek\">ἐ</span>. depende: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 14:4</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 9:27</a>; 16:19; 18:17.</p>\n<p class=\"entry-text\"><b>② Tomar sob custódia: prender, deter.</b> (Cf. Demóstenes 33, 9.) <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:33</a>.</p>\n<p class=\"entry-text\"><b>③ Apoderar-se de alguma coisa comprometedora: surpreender, apanhar.</b> Extensão figurada de ①, com duplo genitivo (cf. ①): <i>apanhar alguém em alguma coisa</i>, <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">λόγου</span>, <i>apanhá-lo em algo que disse</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 20:20</a>; também <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ῥήματος</span>, versículo 26.</p>\n<p class=\"entry-text\"><b>④ Agarrar para fazer algo seu: tomar posse de, apropriar-se de.</b> Extensão figurada de ① (Heródoto 1, 127; 5, 23; Políbio 6, 50, 6; 15, 8, 12; Pv 4:13): <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰωνίου</span> <span class=\"greek\">ζωῆς</span>, <i>da vida eterna</i>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 6:12</a>; cf. versículo 19.</p>\n<p class=\"entry-text\"><b>⑤ Ocupar-se com, interessar-se por.</b> O contexto de <span class=\"greek\">ἀγγέλων</span>, <span class=\"greek\">σπέρματος</span> <span class=\"greek\">Ἀβραάμ</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:16</a>, sugere a tradução <i>interessar-se por</i>, provavelmente no sentido de <i>ajudar</i> (escólio a Ésquilo, Pers. 742 [mas ver K. Dolfe, ZNW 84, 1993, quanto ao problema textual]; Sir 4:11). Aqui talvez caiba a variante de leitura <span class=\"greek\">ἐπιλαβών</span> (mas a voz ativa não é empregada de outro modo na LXX nem no NT), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.72\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:72</a>. — M-M; TW.</p></section></article>\n<article id=\"entry-epilampo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐπιλάμπω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦epilámpō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Futuro, terceira pessoa singular, <span class=\"greek\">ἐπιλάμψει</span>, Is 4:2; primeiro aoristo <span class=\"greek\">ἐπέλαμψα</span> (Homero e posteriores; inscrições; PGM 3, 135; LXX, Fílon). <b>Produzir a emissão de fortes raios de luz: irradiar, resplandecer, brilhar.</b> Literalmente (Dio Chrys. 71 [21], 14), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 12:7</a> D (IGUR 1287, 8; sobre luz divina, Jâmblico, Myst. 3, 2: <span class=\"greek\">φωτὸς</span> <span class=\"greek\">ἐπιλάμψαντος</span>). Figuradamente, acerca da misericórdia divina: <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἐπιλάμψῃ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔλεος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, <i>quando resplandecer a misericórdia do Senhor</i>, Hs 4:2 (Is 4:2, sobre Deus; Wsd 5:6, sobre a justiça; Proclo, Theol. 185, p. 162, 4: <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἄνωθεν</span> <span class=\"greek\">ἐπιλάμπον</span>). Em inscrições, termo técnico para o «resplandecimento» de um governante a quem são prestadas honras divinas: SIG 814, 34; 900, 26; OGI 669, 7; de modo semelhante, POslo 126, 5 [161 d.C.]. — New Docs 4, p. 36.</p></section></article>"};
